static int flac_get_max_frame_size(int blocksize, int ch, int bps)
{
    int count = 16;
    int payload;

    count += ch * ((7 + bps + 7) / 8);

    if (ch == 2) {
        payload = 2 * bps;
        payload += 1;
    } else {
        payload = ch * bps;
    }

    payload *= blocksize;
    payload += 7;
    payload /= 8;

    count += payload;
    count += 2;
    return count;
}
